head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.delLowP = 0;
scwin.stFocusGrid = false;

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    await scwin.gform_onload();
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/ceochg.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/*---------------------------------------------------------------------------------------------------------*/
scwin.js_com_Isurcd; // 발행사코드
scwin.js_com_Isurnm; // 발행사명
scwin.js_com_market = $c.frame.path("/top").ps_market; // 운영관리는 "" 로 처리 상장공시처리에서는 세션으로 처리
if (scwin.js_com_market !== "1" && scwin.js_com_market !== "2") scwin.js_com_market = "";

// if (typeof(js_com_market)=="undefined") {js_com_market = ""; }else{ js_com_market = js_market; }
scwin.js_com_left;
scwin.js_com_top;

/**
 * @method
 * @name IsurTagetPos
 * @description Isur Taget Pos 처리
 * @param {*} grdObj grdObj
 * @param {*} grdObj2 grdObj2
 * @param {*} Tg Tg
 * @returns {void}
 * @hidden N
 */
scwin.IsurTagetPos = function(grdObj, grdObj2, Tg) {
    let cL = 7;
    let cT = 53;
    if (Tg === "G") {
        cL = 3;
        cT = 22;
    }
    scwin.js_com_left = grdObj.style.left;
    scwin.js_com_left = scwin.js_com_left.substring(0, scwin.js_com_left.length - 2);
    scwin.js_com_left = Number(scwin.js_com_left) + cL;
    scwin.js_com_top = grdObj.style.top;
    scwin.js_com_top = scwin.js_com_top.substring(0, scwin.js_com_top.length - 2);
    scwin.js_com_top = Number(scwin.js_com_top) + cT;

};

/**
 * @method
 * @name comGridPos
 * @description com Grid Pos 처리
 * @param {*} grdObj grdObj
 * @param {*} grdObj2 grdObj2
 * @returns {void}
 * @hidden N
 */
scwin.comGridPos = function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj;
    // 발행사코드
    scwin.js_com_Isurnm = grdObj2;
    // 발행사명
    $c.cm.IsurTagetPos(grdObj, grdObj2, 'G');
    Grd_com_isur.style.left = scwin.js_com_left;
    Grd_com_isur.style.top = scwin.js_com_top;

};

/**
 * @method
 * @name IsurcdSearch
 * @description Isurcd Search 처리
 * @param {*} grdObj grdObj
 * @param {*} grdObj2 grdObj2
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.IsurcdSearch = async function(grdObj, grdObj2) {
    scwin.js_com_Isurcd = grdObj;
    // 발행사코드
    scwin.js_com_Isurnm = grdObj2;
    // 발행사명
    $c.cm.IsurTagetPos(grdObj, grdObj2, 'E');
    const options = {
        id: "ULDCOM00007",
        title: "발행회사검색창",
        type: "pageFramePopup",
        width: "295px",
        height: "400px"
    };

    const data = {
        // TO-DO : 팝업으로 전달할 파라미터 설정
    };

    const result = await $c.win.openPopup("/common/ULDCOM00007.gfm", options, data);
    // TO-DO : result 값 확인 후 업무 로직 추가

};

/**
 * @method
 * @name isurSearch_Rtn
 * @description isur Search Rtn 처리
 * @param {*} pJongCode pJongCode
 * @param {String} pJongNm pJongNm
 * @returns {void}
 * @hidden N
 */
scwin.isurSearch_Rtn = function(pJongCode, pJongNm) {
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);

};

/**
 * @method
 * @name comIsurSync
 * @description com Isur Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.comIsurSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/isurcd.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name comIsur
 * @description com Isur 처리
 * @param {*} grdObj grdObj
 * @param {*} grdObj2 grdObj2
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.comIsur = async function(grdObj, grdObj2) {
    Grd_com_isur.style.display = "none";
    $c.cm.fn_com_grid_pos(grdObj, grdObj2);
    const sbmOptions = {
        id : "sbm_MxDataSet_com_isur",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_com_isur=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    $c.cm.fn_com_isur_sync();
};

/**
 * @method
 * @name comConfirmSet
 * @description com Confirm Set 처리
 * @returns {void}
 * @hidden N
 */
scwin.comConfirmSet = function() {
    const pJongCode = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "ISUR_CD");
    const pJongNm = MxDataSet_com_isur.getCellData(MxDataSet_com_isur.getRowPosition(), "COM_ABBRV");
    scwin.js_com_Isurcd.setValue(pJongCode);
    scwin.js_com_Isurnm.setValue(pJongNm);
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name comIsurNm
 * @description com Isur Nm 처리
 * @param {*} keyCode keyCode
 * @returns {void}
 * @hidden N
 */
scwin.comIsurNm = function(keyCode) {
    let cnt = 0;
    const len = scwin.js_com_Isurcd.getValue().length;
    const txtVal = scwin.js_com_Isurcd.getValue().toUpperCase();
    let foColum = 1;
    Grd_com_isur.Redraw = "false";
    if (len > 1) {
        if (isNaN(txtVal)) {
            foColum = 1;
        } else {
            foColum = 2;
        }
    }
    if (foColum === 1) {
        MxDataSet_com_isur.sort("+COM_ABBRV", 0);
        // MxDataSet_com_isur.sort(); // W-Craft 주석처리
        for (i = 1; i <= MxDataSet_com_isur.getRowCount(); i++) {
            let name = MxDataSet_com_isur.getCellData(i, "COM_ABBRV").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    } else {
        MxDataSet_com_isur.sort("+ISUR_CD", 0);
        // MxDataSet_com_isur.sort(); // W-Craft 주석처리
        for (i = 1; i <= MxDataSet_com_isur.getRowCount(); i++) {
            let name = MxDataSet_com_isur.getCellData(i, "ISUR_CD").substring(0, len).toUpperCase();
            if (txtVal <= name) {
                cnt = i;
                break;
            }
        }
    }
    Grd_com_isur.Redraw = "true";
    MxDataSet_com_isur.setRowPosition(cnt + 11, 0);
    MxDataSet_com_isur.setRowPosition(cnt, 0);
};

/**
 * @method
 * @name isNumber
 * @description 숫자인지 확인
 * @param {*} sVal sVal
 * @returns {void}
 * @hidden N
 */
scwin.isNumber = function(sVal) {
    // 숫자인지 확인
    if (('0' < sVal) || ('9' > sVal)) {
        return true;
    } else {
        return false;
    }
};

/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description -----------------------------------------------------------------------------------------------------
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_OnLoadCompleted = function(rowcount) {
    textbox_1.setValue("총 " + rowcount + "건");
};

/**
 * @method
 * @name gform_onload
 * @description gform onload 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.gform_onload = async function() {
    $c.cm.PanelToGroupBox_01(panel_1);
    // PanelToGroupBox_02(panel_2);
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    toDaySet(txb_date1);
    toDaySet(txb_date2);
    $c.cm.fn_com_isur(isur_cd, isur_nm);
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_sys_search_onclick = async function() {
    if (txb_date1.getValue() !== "" && txb_date2.getValue() !== "") {
        await scwin.listSync(); // alert();

    } else {
        await $c.win.alert("일자를 지정하십시요");
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description btn_cal 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_cal_onclick = function() {
    popUpCalendar(txb_date_bg1, 'txb_date1', 'yyyymmdd'); // alert('image_2.onclick');

};

/**
 * @method
 * @name image_6_onclick
 * @description image_6 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.image_6_onclick = function() {
    $c.cm.IsurcdSearch(isur_cd, isur_nm);
};

/**
 * @method
 * @name image_2_onclick
 * @description image_2 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.image_2_onclick = function() {
    popUpCalendar(txb_date_bg2, 'txb_date2', 'yyyymmdd'); // alert('image_2.onclick');

};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_toExcel_onclick = function() {
    $c.data.downloadGridViewExcel(MxGrid_1, {fileName: "대표이사변경", type: "2"});
};

/**
 * @method
 * @name MxGrid_1_OnClick
 * @description MxGrid_1 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.MxGrid_1_OnClick = function(row, colid) {
    scwin.delLowP = row;
    const sCd = MxDataSet.getCellData(row, "ACPT_NO");
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    if (kcode === '13') {
        $c.cm.fn_com_Confirm_set();
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    $c.cm.fn_com_Confirm_set();
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    scwin.stFocusGrid = true;
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    scwin.stFocusGrid = false;
    Grd_com_isur.style.display = "none";
};

/**
 * @method
 * @name isur_cd_onblur
 * @description isur_cd 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.isur_cd_onblur = function() {
    if (scwin.stFocusGrid === false) {
        Grd_com_isur.style.display = "none";
    }
    if (ISUR_CD.value === "") {
        isur_nm.setValue("");
    }
};

/**
 * @method
 * @name isur_cd_onfocus
 * @description isur_cd 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.isur_cd_onfocus = function() {
    Grd_com_isur.style.display = "";
};

/**
 * @method
 * @name isur_cd_onkeyup
 * @description isur_cd 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.isur_cd_onkeyup = function() {
    if (window.event.keyCode === 40) {
        // 아래화살표눌렀을때 그리드로 포커스
        Grd_com_isur.focus();
    } else {
        if (window.event.keyCode === 13) {
            $c.cm.fn_com_Confirm_set();
        } else {
            $c.cm.fn_com_isur_nm(window.event.keyCode);
        }
    }
};
